#include <stdint.h>
#include "stm32f407xx.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

volatile uint8_t led_index = 0;

void RCC_Config(void)
{
	RCC->CR |= (1 << 16);
	while(!((RCC->CR) & (1 << 17)));
	RCC->CR |= (1 << 19);
	RCC->CR &= ~(1 << 24);

	RCC->PLLCFGR &= ~(1 << 22);
	RCC->PLLCFGR |= (1 << 22);
	RCC->PLLCFGR &= ~(0x3F << 0);
	RCC->PLLCFGR |= (8 << 0);
	RCC->PLLCFGR &= ~(0x1FF << 6);
	RCC->PLLCFGR |= (0x150 << 6);
	RCC->PLLCFGR &= ~(3 << 16);

	RCC->CR |= (1 << 24);
	while(!(RCC->CR & (1 << 25)));

	// 5. FLASH AYARLARI (ÇÖKMEYİ ENGELLEYEN KRİTİK ADIM)
	// 168 MHz ve 3.3V için 5 Wait State gerekir. Ayrıca Prefetch ve Cache'ler açılmalıdır.
	FLASH->ACR = FLASH_ACR_ICEN | FLASH_ACR_DCEN | FLASH_ACR_PRFTEN | FLASH_ACR_LATENCY_5WS;

	RCC->CFGR &= ~(0xF << 4);
	RCC->CFGR |= (4 << 13);
	RCC->CFGR |= (5 << 10);

	RCC->CFGR |= (2 << 0);
	while ((RCC->CFGR & (3 << 2)) != (2 << 2));

	RCC->CR &= ~(1 << 0);
}


void Clock_Config(void)
{
	RCC->AHB1ENR |= (1 << 0); // GPIOA enable
	RCC->AHB1ENR |= (1 << 3); // GPIOD enable
	RCC->APB1ENR |= (1 << 4); // TIM6 enable
	RCC->APB1ENR |= (1 << 5); // TIM7 enable
}

void GPIO_Config(void)
{
	GPIOD->MODER &= ~(0xFF << 24);
	GPIOD->MODER |= (0x55 << 24);
	GPIOA->MODER &= ~(3 << 2);
	GPIOA->MODER |= (1 << 2);
	GPIOA->MODER &= ~(3 << 0);
}

void TIM6_Config(void)
{
	TIM6->PSC = 42000-1;   // Timer Saati Ayarı (PSC = 41999) -> Timer frekansı 2 KHz oludu.
	TIM6->ARR = 1000-1;    // yarım saniyede bir yanmasını istiyoruz

	TIM6->CR1 |= (1 << 2); // Gereksiz kesmeleri engelemek için sadece sayaç baştan sona sayıp taştıgında kesme üretmesini saglayan URS biti.
	TIM6->CR1 |= (1 << 7); // Hız değişimlerinin anında degil, bir sonraki turda geçerli olması için ARPE biti.

	TIM6->DIER |= (1 << 0);// Timer6 in taşma durumunda işlemciye haber vermesi için UIE biti enable yapıldı.

	TIM6->EGR |= (1 << 0); // Yazdıgı PSC ve ARR degerinin donanınmdaki shadow registers anında geçmesi için UG bitini "1" yaprım.

	NVIC_EnableIRQ(TIM6_DAC_IRQn); // TIM6'dan gelen kesmeleri kabul et.
}

void TIM7_Config(void)
{
	TIM7->PSC = 42000-1;   // Hızını yine 2 KHz yaptım.
	TIM7->ARR = 4000-1;    // 2 saniye yaptım bir periyodu

	TIM7->CR1 |= (1 << 3); // TIM 7 sadece butona basıldıgında sadece 1 kez çalışıp kendini durduruyor.

	TIM7->CR1 |= (1 << 2); // Gereksiz kesmeleri önemsemez sadece overflow durmunda kesme üretmesini saglar.

	TIM7->DIER |= (1 << 0);// Timer7 taşma durumunda işlemciye haber verebilmesi için 1 yapılmalı UIE biti.

	TIM7->EGR |= (1 << 0);

	NVIC_EnableIRQ(TIM7_IRQn); //NVIC üzerinden bu kez TIM7'yi aktif et.

}



int main(void)
{
	RCC_Config();
	Clock_Config();
	GPIO_Config();
	TIM6_Config();
	TIM7_Config();

    /* Loop forever */
	TIM6->CR1 |= (1 << 0);

	while(1)
	{
		 if(GPIOA->IDR & (1 << 0))       // Butona (PA0) basıldı mı kontrolü
		 {
			 GPIOA->ODR |= (1 << 1);     // buzzer çalar.
			 TIM7->CR1 |= (1 << 0);      // TIM7'yi başlat (CEN = 1)
			 while(GPIOA->IDR & (1 << 0)); // Butondan el çekilene kadar bekle (Debounce)
		 }


	}
}



void TIM6_DAC_IRQHandler(void)
{

	if(TIM6->SR & (1 << 0))          // Bayrağı kontrol et
	{
		TIM6->SR &= ~(1 << 0);       // Bayrağı temizle
		GPIOD->ODR &= ~(0xF << 12);
		GPIOD->ODR |=  (1 << (12+led_index));

		// Bir sonraki kesme (500 ms sonra) 0.5 sn için indeksi artır
		led_index++;
		if(led_index > 3)
		{
			led_index = 0;
		}
	}
}

void TIM7_IRQHandler(void)
{
	if(TIM7->SR & (1 << 0))
	{
		TIM7->SR &= ~(1 << 0);
		GPIOA->ODR &=  ~(1 << 1);    // buzzeri susturmak için PA1 pinini '0' yapıyoruz.
	}
}

